import time
import random


def retry(times, delay=0.5):
    """Retry a function when it raises."""

    def decorator(fn):
        def wrapper(*args, **kwargs):
            last = None
            for attempt in range(times):
                try:
                    return fn(*args, **kwargs)
                except Exception as err:
                    last = err
                    wait = delay * 2 ** attempt
                    wait += random.random() * 0.1
                    time.sleep(wait)
            raise last

        return wrapper

    return decorator


